import csv
from pathlib import Path
P=Path(__file__).parents[1]
labels={'T06':('0','Обычный срок завтра без усиления.'),'T07':('0','Ожидание не означает ускорение.'),'T10':('1','Побыстрее — явный положительный критерий.'),'T15':('1','Рекламная срочность учитывается.'),'T16':('0','Сегодня без требования ускорить.'),'T17':('1','Текущая остановка обслуживания.'),'T18':('0','Обычная помощь без сигнала срочности.'),'T19':('1','Призыв прямо сейчас.'),'T22':('0','Инструкция прямо относит этот срок к обычным.'),'T26':('1','Явное срочно; важность причины не оценивается.'),'T27':('0','Просрочка без требования ускорения.'),'T31':('1','Первым делом — положительный критерий.'),'T32':('1','Маркетинговый призыв сейчас.'),'T33':('0','Инструкция прямо исключает такую жалобу без ускорения.'),'T35':('0','Предпочтение закончить сегодня.'),'T38':('1','При первой возможности — положительный критерий.'),'T41':('1','Явное срочно независимо от темы.'),'T44':('0','Повторение просьбы не означает срочность.'),'T45':('1','Как увидишь — положительный критерий.'),'T46':('0','Условное предпочтение сегодня.'),'T49':('1','До закрытия возможности полчаса.'),'T50':('0','Нет требования ускорения.'),'T54':('0','Длительная задержка без требования ускорить.'),'T56':('1','Как можно скорее — прямой критерий.'),'T57':('0','Обычный срок завтра без усиления.'),'T60':('0','Общая зависимость работы без немедленной остановки.'),'T61':('0','Пересказ чужого слова без присоединения автора.'),'T65':('?','Пограничный пример из общей инструкции.'),'T66':('1','Немедленно — прямой критерий.'),'T70':('1','Ускорьте — прямой критерий.')}
rows=list(csv.DictReader((P/'data/disputed30.csv').open(encoding='utf-8-sig')))
with (P/'annotations/revised_c.csv').open('w',encoding='utf8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['id','label','reason']);w.writeheader()
 for row in rows:
  label,reason=labels[row['id']];w.writerow(dict(id=row['id'],label=label,reason=reason))
